-- US admission requirements, retry of schools that failed in wave 4 (checked 13 Nov 2026). Needs step181.
update schools set admission_info = $q${"ug": "First-year applicants must send an ACT or equivalent SAT score (without writing) and an official evaluation of international high school results from an accepted agency such as World Education Services.", "english": "TOEFL is required. Minimum scores are 69 (internet-based), 194 (computer-based) or 525 (paper-based). Applicants from English-speaking countries, and those with a US high school diploma or 30 US college hours, are exempt.", "how_to_apply": "Apply through International Student Services. After admission, send a Certified Declaration of Financial Support for one academic year to the Young Hall office in Jefferson City.", "documents": "Test scores, credential evaluation, certified declaration of financial support, proof of measles, mumps and rubella shots for on-campus students, and a TB blood test and chest x-ray done in the US within six weeks before classes.", "fees_link": "https://www.lincolnu.edu/web/international/apply", "sources": ["https://www.lincolnu.edu/web/international/apply", "https://www.lincolnu.edu/web/international/admissions"]}$q$::jsonb, admission_link = $q$https://www.lincolnu.edu/web/international/apply$q$, admission_checked = '2026-11-13' where id = '89532558-3130-421e-b846-f9ed3b65296b' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "Apply through the undergraduate application portal and upload the full I-20 application and Affidavit of Support. I-20 processing takes 5 to 10 business days after all documents are received.", "deadlines": "Fall: June 15. Spring: November 15. Students already in the US who transfer by SEVIS may have later dates.", "documents": "Signed I-20 application and affidavit of support, passport photo page, English bank statement dated within the last 3 months, copy of any current visa, and an Affidavit of Free Room and Board if living free with a family member or friend. Funds must cover one full year of cost (2026-27 estimate: $54,336).", "fees_link": "https://inside.montclair.edu/documents/bloomfield-i-20-application-ay-2026-27", "sources": ["https://inside.montclair.edu/resources/global-engagement-office/bloomfield-college-accepted-international-students", "https://inside.montclair.edu/documents/bloomfield-i-20-application-ay-2026-27"]}$q$::jsonb, admission_link = $q$https://inside.montclair.edu/documents/bloomfield-i-20-application-ay-2026-27$q$, admission_checked = '2026-11-13' where id = '69bc02a7-37b2-4729-8c90-52618e424eb7' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send their secondary school record in English, a letter of recommendation from a school official, a Certificate of Financial Support, and SAT or ACT results if available. Foreign transcripts need a course-by-course evaluation (for example by World Education Services).", "pg": "Bachelor's degree or equivalent with at least a 2.70 GPA, WES credential evaluation, official transcripts, three recommendation letters and a statement of purpose. International applicants also send an Affidavit of Support (Form I-134) and a notarized financial statement showing at least $24,000 per academic year.", "english": "Undergraduate: TOEFL paper 550, TOEFL internet 80, or IELTS 7.0 for non-native English speakers. Graduate: TOEFL is required where English is not the language of instruction.", "how_to_apply": "Undergraduates follow the International Students page and graduate applicants apply at gradapply.suno.edu. The graduate school will not admit applicants who entered the US on an I-20 from another school.", "deadlines": "Deadlines are shown in a chart image on the International Students page, so exact dates could not be confirmed.", "documents": "Transcripts, credential evaluation, certificate of financial support, test scores, and for graduate study recommendation letters and a statement of purpose.", "fees_link": "https://www.suno.edu/page/international-students", "sources": ["https://www.suno.edu/page/international-students", "https://www.suno.edu/page/graduate-studies-admission-requirements", "https://www.suno.edu/page/international-studentsofsuno"]}$q$::jsonb, admission_link = $q$https://www.suno.edu/page/international-students$q$, admission_checked = '2026-11-13' where id = '4d663965-2090-4747-9449-f9ab46d6bd39' and country = 'United States';
update schools set admission_info = $q${"ug": "ACT or SAT scores are not required for admission but are used for academic scholarships. Send a high school transcript (official preferred) and a college transcript if you attended college.", "english": "TOEFL iBT 61 (paper 500, computer 173), IELTS Academic 5.5, or Duolingo English Test 85. Applicants from countries on the school's recognized English-speaking list are exempt.", "how_to_apply": "Upload all documents with the application. Unofficial copies are accepted for review, but you must bring the originals when you arrive.", "deadlines": "The page lists Spring 2024 (November 15, 2023) and Fall 2024 (July 15, 2024). These dates are old, so check the school for current dates.", "documents": "Passport copy, transcripts, Financial Guarantee Form, bank letter in English and US dollars dated within six months showing funds cover cost of attendance, and vaccination records or an exemption form.", "fees_link": "https://opsu.edu/international-students/admission-requirements-for-international-students", "sources": ["https://opsu.edu/international-students/admission-requirements-for-international-students"]}$q$::jsonb, admission_link = $q$https://opsu.edu/international-students/admission-requirements-for-international-students$q$, admission_checked = '2026-11-13' where id = '18059a08-fa7a-4e70-bd2d-b5087ddb31cc' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshman applicants must have finished a secondary school comparable to a US high school. Decisions use grades, subjects studied, and ACT or SAT scores.", "english": "An English language requirement must be completed, but the page does not list accepted tests or minimum scores.", "how_to_apply": "Complete the LSUA application, send transcripts, meet the English requirement, send ACT or SAT scores, submit the Confidential Financial Information Form and Affidavit of Support, pay the SEVIS fee, and complete the student visa interview.", "deadlines": "Materials are due at least 60 days before the semester. On-campus deadlines: Fall August 1, Spring December 1, Summer May 1.", "documents": "Transcripts, ACT or SAT scores, Confidential Financial Information Form and Affidavit of Support.", "fees_link": "https://www.lsua.edu/admissions/apply/international-students", "sources": ["https://www.lsua.edu/apply/international-students/", "https://www.lsua.edu/admissions/apply/international-students"]}$q$::jsonb, admission_link = $q$https://www.lsua.edu/admissions/apply/international-students$q$, admission_checked = '2026-11-13' where id = 'a591db13-439b-4755-b02b-4068b4ddcfc8' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a minimum 2.00 high school GPA shown on an official document-by-document credential evaluation (including GPA) from a NACES member or InCred. Do not send foreign transcripts directly to the college. Transfers need a 2.00 GPA and a course-by-course evaluation of non-US coursework.", "english": "TOEFL iBT 69 or IELTS 6. Waivers exist for students placed into college-level English by ACCUPLACER, or transfers with English 1101 or 1102 at a US accredited school with a C or better.", "how_to_apply": "Apply through the Grizzly Profile and pay the application fee. Admitted students then receive instructions for sending financial documents.", "deadlines": "Priority: Fall May 1, Spring November 1, Summer April 1. Regular for Spring 2027: application December 1, documents December 15.", "application_fee": "$30, non-refundable", "documents": "Credential evaluation, English test score, bank statement or bank letter on letterhead showing funds for one academic year, signed Affidavit of Financial Support if a sponsor pays, and immunization records.", "fees_link": "https://www.ggc.edu/admission-aid/international-student-services/international-student-admission-requirements", "sources": ["https://www.ggc.edu/admission-aid/international-student-services/international-student-admission-requirements"]}$q$::jsonb, admission_link = $q$https://www.ggc.edu/admission-aid/international-student-services/international-student-admission-requirements$q$, admission_checked = '2026-11-13' where id = 'd3493a16-994e-4ba2-9a36-da59f212e0a0' and country = 'United States';
